import { getProjectDetails, type GetProjectDetailsResponse } from '~/client';

export const useProjectDetails = defineQuery(() => {
  const route = useRoute('projects-id');
  const projectId = computed(() => route.params.id?.toString() || '');

  const {
    data: projectDetails,
    error,
    isLoading,
  } = useQuery({
    key: () => ['project', projectId.value],
    query: () => getProjectDetails({ composable: '$fetch', path: { project_id: projectId.value } }),
    enabled: () =>
      !!projectId.value &&
      (route.name === 'projects-id' ||
        route.name === 'projects-id-ballot-template' ||
        route.name === 'projects-id-dashboard' ||
        route.name === 'projects-id-dashboard-responses' ||
        route.name === 'projects-id-dashboard-team'),
  });

  return {
    projectId,
    projectDetails,
    error,
    isLoading,
  };
});
