import type { BallotTemplateState } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

export const ballotTemplateStateVariants: Record<BallotTemplateState, BadgeVariants> = {
  uploaded: 'default',
  marked: 'default',
  ready: 'success',
  failed: 'destructive',
};

export function getBallotTemplateStateVariant(state: BallotTemplateState): BadgeVariants {
  return ballotTemplateStateVariants[state] ?? 'default';
}
